const body=$('Entrada — tasas').first().json.body||{};
const selection=body.selection||{}; const date=String(body.date||'');
const rows=$('Consultar ARESEP').first().json.value||[];
const value=Array.isArray(rows)?rows.filter(r=>Number(r.anho)===Number(date.slice(0,4))&&Number(r.id_Mes)===Number(date.slice(5,7))&&r.empresa===selection.company&&r.tipoTarifa===selection.tariff&&String(r.bloque).trim()===String(selection.block||'').trim()).slice(0,3):[];
return [{json:{exchange:$('Consultar Hacienda').first().json,electricity:{value}}}];

const data = $input.first().json.body ?? $input.first().json;
const emailIsValid = value => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(value || ''));
const amount = Number(data.amountCrc);
if (!data.requestId || !Number.isSafeInteger(amount) || amount <= 0 || data.currency && data.currency !== 'CRC' || !emailIsValid(data.customerEmail) || !emailIsValid(data.adminEmail) || !data.validUntil || !data.notes) {
  throw new Error('La cotización o sus destinatarios no son válidos.');
}
const escapeHtml = value => String(value ?? '').replace(/[&<>\"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', "'": '&#39;' }[char]));
const money = value => new Intl.NumberFormat('es-CR', { style: 'currency', currency: 'CRC', maximumFractionDigits: 0 }).format(Number(value) || 0);
const labels = { materialCrc: 'Material', wearCrc: 'Desgaste del material', electricityCrc: 'Electricidad', postProcessCrc: 'Postprocesado', designCrc: 'Diseño', otherCostsCrc: 'Otros costos', costSubtotalCrc: 'Costo calculado' };
const breakdown = data.breakdown && typeof data.breakdown === 'object' ? data.breakdown : {};
const rows = Object.entries(labels).filter(([key]) => Number.isFinite(Number(breakdown[key]))).map(([key, label]) => `<tr><td style="padding:8px 12px;border-top:1px solid #ded8d0">${label}</td><td style="padding:8px 12px;border-top:1px solid #ded8d0;text-align:right">${money(breakdown[key])}</td></tr>`).join('');
const validUntil = new Intl.DateTimeFormat('es-CR', { dateStyle: 'long', timeZone: 'UTC' }).format(new Date(`${data.validUntil.slice(0, 10)}T12:00:00Z`));
const name = escapeHtml(data.customerName || '');
const notes = escapeHtml(data.notes).replace(/\n/g, '<br>');
const piece = escapeHtml(data.piece || `Solicitud ${data.requestId}`);
const quantity = Number.isSafeInteger(Number(data.quantity)) ? Number(data.quantity) : '—';
const material = escapeHtml(data.material || 'Por confirmar');
const html = `<main style="max-width:640px;margin:auto;color:#211c17;font:16px/1.55 Arial,sans-serif"><p style="font-size:12px;letter-spacing:.14em;color:#c94713">VÉRTICE CR · COTIZACIÓN ${escapeHtml(data.requestId)}</p><h1 style="font-size:26px">Hola${name ? ` ${name}` : ''},</h1><p>Preparamos la cotización de tu solicitud. Revisá el alcance, el monto y la vigencia antes de aprobarla.</p><table style="width:100%;border-collapse:collapse;background:#f5f1eb"><tbody><tr><td style="padding:12px">Encargo</td><td style="padding:12px;text-align:right">${piece}</td></tr><tr><td style="padding:12px">Cantidad</td><td style="padding:12px;text-align:right">${quantity}</td></tr><tr><td style="padding:12px">Material</td><td style="padding:12px;text-align:right">${material}</td></tr>${rows}</tbody></table><p style="font-size:22px;font-weight:bold">Total: ${money(amount)}</p><p><strong>Válida hasta:</strong> ${escapeHtml(validUntil)}</p><p><strong>Alcance y condiciones</strong><br>${notes}</p><p>Respondé a este correo si necesitás aclarar algún detalle. La fabricación inicia después de tu aprobación y de completar el proceso de pago.</p><p style="color:#70685f;font-size:13px">Vértice CR · Impresión 3D</p></main>`;
return [{ json: { customerEmail: data.customerEmail, adminEmail: data.adminEmail, subject: `${data.mode === 'DEMO' ? '[DEMO] ' : ''}${data.test ? '[PRUEBA] ' : ''}Cotización Vértice CR · Solicitud ${data.requestId}`, html, deliveryKey: data.deliveryKey } }];

const sent=$input.first().json; const context=$('Validar y preparar correo').first().json;
if (!sent.id || !context.deliveryKey) throw new Error('Gmail no confirmó identificador');
return [{json:{delivered:true,messageId:sent.id,deliveryKey:context.deliveryKey}}];
